package com.xiaomiscalesync.ble

import com.google.gson.JsonParser
import com.xiaomiscalesync.crypto.Vectors

/**
 * One MiBeacon advertisement fixture from the committed
 * `beacon_vectors.json` (generated by `scripts/gen_vectors.py --beacon`).
 */
data class BeaconFixture(
    val name: String,
    val mac: String,
    val bindKey: ByteArray,
    val serviceData: ByteArray,
    val frameControl: Int,
    val frameCounter: Int,
    val solicit: Boolean,
    val eventKey: Long,
    val objects: List<Pair<Int, ByteArray>>,
    val weighIn: BroadcastWeighIn?,
)

/** Loads `beacon_vectors.json` from the unit-test resources. */
object BeaconVectors {

    fun load(): List<BeaconFixture> {
        val url = checkNotNull(BeaconVectors::class.java.classLoader?.getResource("beacon_vectors.json")) {
            "missing test resource beacon_vectors.json"
        }
        val array = url.openStream().bufferedReader().use { reader ->
            JsonParser.parseReader(reader).asJsonArray
        }
        return array.map { element ->
            val obj = element.asJsonObject
            val objects = obj.getAsJsonArray("objects").map { item ->
                val pair = item.asJsonObject
                pair.get("id").asInt to Vectors.decodeHex(pair.get("value").asString)
            }
            BeaconFixture(
                name = obj.get("name").asString,
                mac = obj.get("mac").asString,
                bindKey = Vectors.decodeHex(obj.get("bindKey").asString),
                serviceData = Vectors.decodeHex(obj.get("serviceData").asString),
                frameControl = obj.get("frameControl").asInt,
                frameCounter = obj.get("frameCounter").asInt,
                solicit = obj.get("solicit").asBoolean,
                eventKey = obj.get("eventKey").asLong,
                objects = objects,
                weighIn = obj.get("weighIn")?.takeUnless { it.isJsonNull }?.let { weighIn ->
                    val w = weighIn.asJsonObject
                    BroadcastWeighIn(
                        profileId = w.get("profileId").asInt,
                        weightGrams = w.get("weightGrams").asInt,
                        unixTs = w.get("unixTs").asLong,
                    )
                },
            )
        }
    }
}
